{"chunk_id":"25e4c8","wall_time_seconds":0.000004471,"exit_code":0,"original_token_count":2434,"output":""""JSON Merge Patch and JSON Patch application helpers."""
import copy


def merge_patch(target, patch):
    """Apply RFC 7386 merge patch and return a new JSON-compatible value."""
    if not isinstance(patch, dict):
        return copy.deepcopy(patch)
    out = copy.deepcopy(target) if isinstance(target, dict) else {}
    for key, value in patch.items():
        if value is None:
            out.pop(key, None)
        else:
            out[key] = merge_patch(out.get(key), value)
    return out


def _parts(pointer):
    if pointer == "":
        return []
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        raise ValueError("invalid JSON pointer")
    parts = []
    for raw in pointer[1:].split("/"):
        i = 0
        while i < len(raw):
            if raw[i] == "~":
                if i + 1 >= len(raw) or raw[i + 1] not in "01":
                    raise ValueError("invalid JSON pointer escape")
                i += 2
            else:
                i += 1
        parts.append(raw.replace("~1", "/").replace("~0", "~"))
    return parts


def _index(part, length, allow_end=False):
    if not part or (len(part) > 1 and part[0] == "0") or not part.isdigit():
        raise ValueError("invalid array index")
    index = int(part)
    if index > length or (index == length and not allow_end):
        raise ValueError("array index out of range")
    return index


def _get(root, path):
    cur = root
    for part in path:
        cur = cur[_index(part, len(cur))] if isinstance(cur, list) else cur[part]
    return cur


def _parent(root, path):
    if not path:
        return None, None
    return _get(root, path[:-1]), path[-1]


def _remove(root, path):
    if not path:
        return None
    parent, key = _parent(root, path)
    if isinstance(parent, list):
        return parent.pop(_index(key, len(parent)))
    return parent.pop(key)


def _add(root, path, value):
    if not path:
        return copy.deepcopy(value)
    parent, key = _parent(root, path)
    value = copy.deepcopy(value)
    if isinstance(parent, list):
        if key == "-":
            parent.append(value)
        else:
            parent.insert(_index(key, len(parent), allow_end=True), value)
    else:
        parent[key] = value
    return root


def _json_equal(left, right):
    """Compare JSON values (where booleans are distinct from numbers)."""
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left == right
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return left == right
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(_json_equal(a, b) for a, b in zip(left, right))
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(_json_equal(left[k], right[k]) for k in left)
    return type(left) is type(right) and left == right


def apply_json_patch(document, operations):
    """Apply a JSON Patch sequence, returning a fresh document."""
